const item = $input.first();
const j = item.json || {};
const bin = item.binary || {};
const pick = (keys) => { for (const k of keys) { if (j[k] !== undefined && j[k] !== null && String(j[k]).trim() !== '') return String(j[k]).trim(); } return ''; };
const key = Object.keys(bin)[0];
const f = key ? bin[key] : null;
const fileName = f ? String(f.fileName || '') : '';
const ext = fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : '';
const mime = f ? String(f.mimeType || '') : '';
const pasted = pick(['brd_text', 'Or paste the BRD text']);
let kind = 'invalid';
if (f) {
  if (ext === 'pdf' || mime === 'application/pdf') kind = 'pdf';
  else if (['txt', 'md', 'markdown'].includes(ext) || mime.startsWith('text/')) kind = 'text';
} else if (pasted) {
  kind = 'pasted';
}
const out = {
  run_id: 'brd-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
  start_ms: Date.now(),
  project_name: pick(['project_name', 'Project name']) || 'Untitled project',
  em_email: pick(['em_email', 'Engineering Manager email']),
  file_name: fileName,
  file_ext: ext,
  file_kind: kind,
  pasted_text: pasted,
};
return [{ json: out, binary: f ? { data: f } : {} }];

const NL = String.fromCharCode(10);
const CR = String.fromCharCode(13);
const meta = $('Check File Type').first().json;
const j = $input.first().json || {};
let text = '';
if (meta.file_kind === 'pdf') text = String(j.text || '');
else if (meta.file_kind === 'text') text = String(j.data || '');
else text = String(meta.pasted_text || '');
text = text.split(CR).join('');

const errors = [];
const triggers = [];
if (meta.file_kind === 'invalid') {
  errors.push(meta.file_name ? 'Unsupported file type ".' + meta.file_ext + '". Upload a PDF, TXT or MD file.' : 'No BRD provided. Upload a file or paste the BRD text.');
}
if (j.error) errors.push('The file could not be read (it may be corrupted or password protected).');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(meta.em_email || '')) errors.push('The Engineering Manager email is not valid.');
if (meta.file_kind !== 'invalid' && text.trim().length < 400) errors.push('The BRD is too short (' + text.trim().length + ' characters, minimum 400).');
if (text.length > 300000) errors.push('The BRD is too large (over 300,000 characters).');

const CATS = [
  ['nfr', /non[- ]?functional|\bnfr|performance|security|availability|scalab|reliab|complian|usability|accessib|quality attribute|privacy/i],
  ['objectives', /objective|goal|purpose|vision|background|overview|introduction|executive summary|business need|problem statement/i],
  ['scope', /scope|deliverable/i],
  ['integration', /integrat|interface|\bapi|external system|third[- ]party/i],
  ['data', /\bdata\b|reporting|analytics|migration/i],
  ['functional', /functional|feature|requirement|user stor|use case|capabilit|workflow|process/i],
  ['timeline', /timeline|schedule|milestone|deadline|roadmap|phase/i],
  ['stakeholders', /stakeholder|persona|user role|\busers?\b|sponsor|team/i],
  ['risks', /risk|issue/i],
  ['assumptions', /assumption/i],
  ['constraints', /constraint|limitation|dependenc|regulat/i],
  ['budget', /budget|cost|pricing|funding/i],
];
const categorize = (title) => { for (const c of CATS) { if (c[1].test(title)) return c[0]; } return 'other'; };
const isHeading = (line) => {
  const l = line.trim();
  if (!l || l.length > 90) return false;
  if (/^#{1,6}\s+\S/.test(l)) return true;
  if (/^\d+(\.\d+)?[.)]?\s+[A-Za-z][^.]{2,70}$/.test(l) && !/[.;,]$/.test(l)) return true;
  if (/^[A-Z][A-Z0-9 &\/,()-]{3,70}:?$/.test(l)) return true;
  return false;
};

const sections = [];
let cur = null;
for (const line of text.split(NL)) {
  if (isHeading(line)) {
    if (cur) sections.push(cur);
    const title = line.trim().replace(/^#{1,6}\s+/, '').replace(/:$/, '');
    cur = { title: title, lines: [] };
  } else if (cur) {
    cur.lines.push(line);
  }
}
if (cur) sections.push(cur);

const clean = [];
sections.forEach((s) => {
  let content = s.lines.join(NL).trim();
  if (content.length < 20) return;
  if (content.length > 5000) { content = content.slice(0, 5000); triggers.push('section_truncated'); }
  clean.push({ title: s.title.slice(0, 120), content: content });
});
const final = clean.slice(0, 40).map((s, i) => ({ id: 'S' + (i + 1), title: s.title, category: categorize(s.title + ' ' + s.content.slice(0, 120)), content: s.content }));
if (clean.length > 40) triggers.push('sections_capped_at_40');

const cats = Array.from(new Set(final.map(s => s.category)));
const core = ['objectives', 'scope', 'functional', 'nfr'].filter(c => cats.includes(c));
if (!errors.length) {
  if (final.length < 3) errors.push('The BRD structure was not recognised: found ' + final.length + ' headed sections (minimum 3). Use headings such as "1. Objectives", "## Scope" or "FUNCTIONAL REQUIREMENTS".');
  else if (core.length < 2) errors.push('The BRD is missing core sections. Found categories: ' + cats.join(', ') + '. At least two of objectives, scope, functional or non-functional requirements are required.');
}
if (/ignore (all |any )?(previous|prior|above) instructions|disregard (the )?(system|previous)|you are now an? /i.test(text)) triggers.push('prompt_injection_pattern_detected');

return [{ json: {
  run_id: meta.run_id,
  start_ms: meta.start_ms,
  project_name: meta.project_name,
  em_email: meta.em_email,
  file_kind: meta.file_kind,
  valid: errors.length === 0,
  errors: errors,
  sections: final,
  section_count: final.length,
  all_section_ids: final.map(s => s.id),
  categories_found: cats,
  guardrail_triggers: triggers,
  brd_text: text,
} }];

// Routes BRD sections to agents and carries state across Critic revision cycles.
const j = $input.first().json;
const isRevision = !!(j.critic_state && j.base);
const base = isRevision ? j.base : {
  run_id: j.run_id, start_ms: j.start_ms, project_name: j.project_name, em_email: j.em_email,
  brd_hash: j.brd_hash, sections: j.sections, all_section_ids: j.all_section_ids,
  guardrail_triggers: j.guardrail_triggers || [],
};
const cs = isRevision ? j.critic_state : { cycle: 0, feedback: {}, previous_outputs: {}, history: [] };
const sections = base.sections;
const MAP = {
  engineering_plan: null,
  schedule: ['scope', 'functional', 'timeline', 'constraints', 'budget', 'stakeholders', 'assumptions', 'objectives'],
  architecture: ['functional', 'nfr', 'integration', 'data', 'constraints', 'scope'],
  poc: ['objectives', 'scope', 'functional', 'nfr', 'risks', 'integration'],
  tech_stack: ['nfr', 'integration', 'data', 'constraints', 'budget', 'functional', 'stakeholders'],
};
const routing = {}; const summary = {};
Object.keys(MAP).forEach((a) => {
  const cats = MAP[a];
  let picked = cats ? sections.filter(s => cats.includes(s.category) || s.category === 'other') : sections.slice();
  if (!picked.length) picked = sections.slice();
  routing[a] = picked; summary[a] = picked.map(s => s.id);
});
const prev = cs.previous_outputs || {};
const pick = (keys) => { const o = {}; keys.forEach(k => { if (prev[k]) o[k] = prev[k]; }); return o; };
const rev = cs.cycle > 0;
const prior = {
  engineering_plan: rev ? pick(['schedule', 'architecture', 'tech_stack']) : {},
  architecture: rev ? pick(['engineering_plan', 'schedule']) : {},
  poc: rev ? pick(['engineering_plan', 'architecture']) : {},
  tech_stack: rev ? pick(['engineering_plan', 'schedule', 'architecture']) : {},
};
const ragQuery = (base.project_name + ' ' + sections.map(s => s.title + ' ' + String(s.content).slice(0, 300)).join(' ')).toLowerCase();
return [{ json: Object.assign({}, base, {
  cycle: cs.cycle, is_revision: isRevision, feedback: cs.feedback || {}, previous_outputs: prev,
  critic_history: cs.history || [], routing: routing, routing_summary: summary, prior: prior, rag_query: ragQuery,
}) }];

// Demo knowledge base: Past BRDs, Org standards, Templates, Project history, Sample BRDs (training).
// Keyword-relevance retrieval returns citable chunks KB1..KBn. Swap for a vector store in production.
const st = $input.first().json;
const CORPUS = [
  { source: 'Org standards / Delivery playbook v3', tags: 'phase plan delivery milestone discovery design build test launch portal objectives scope', text: 'Standard delivery phases are Discovery (2-4 weeks), Design (2-4 weeks), Build (iterative 2-week sprints), Test and Hardening (min 2 weeks), Launch, and Hypercare (2 weeks). Each phase needs documented exit criteria and an EM sign-off milestone.' },
  { source: 'Org standards / Estimation guideline', tags: 'estimate effort schedule timeline months weeks contingency budget team', text: 'Effort estimates must be in person-days with a confidence level. Add 20% contingency for medium-confidence work and 30% when external integrations are involved. A typical engineer delivers 8-10 person-days of story effort per 2-week sprint.' },
  { source: 'Org standards / Architecture principles', tags: 'architecture security sso saml login encryption encrypted api integration availability concurrent performance', text: 'Customer-facing apps must authenticate through the corporate identity provider (SAML 2.0 or OIDC), encrypt data in transit (TLS 1.2+) and at rest (AES-256), expose services through the API gateway, and run multi-AZ for 99.9% availability targets.' },
  { source: 'Org standards / Technology radar 2026', tags: 'stack react typescript node java postgres cloud users portal web', text: 'ADOPT: React + TypeScript, Node.js (NestJS), Java 21 (Spring Boot), PostgreSQL, Redis, AWS managed services, Terraform. TRIAL: Go for high-throughput services. HOLD: new AngularJS apps, self-managed Kafka clusters.' },
  { source: 'Org standards / Team skills matrix', tags: 'team familiarity skills staffing size admins users', text: 'Engineering teams have HIGH familiarity with React, TypeScript and Node.js, MEDIUM with Java/Spring and AWS EKS, LOW with Go and native mobile. Dedicated QA and DevOps capacity is 1 engineer each per squad.' },
  { source: 'Templates / PoC charter template', tags: 'poc proof concept success criteria scope reduce objectives', text: 'A PoC lasts 2-4 weeks, validates the riskiest assumption first, defines 3-5 measurable success criteria (metric + target), keeps modules behind explicit interfaces, and ends with a go/no-go decision.' },
  { source: 'Project history / Partner portal 2025', tags: 'portal billing integration invoice invoices history', text: 'The 2025 partner portal took 7 months against a 5-month plan; the main delay was the legacy billing API (rate limits, missing pagination). Lesson: run an integration spike in the first 3 weeks and cache read-heavy billing data.' },
  { source: 'Past BRDs / Self-service portal BRD (2024)', tags: 'self service portal password reset invoice account profile accessibility wcag', text: 'A prior self-service BRD scoped account profile, password reset and invoice download; WCAG 2.1 AA accessibility and SSO were mandatory; payments were deferred to phase 2.' },
  { source: 'Sample BRDs (training) / Data platform BRD', tags: 'data reporting analytics migration', text: 'Sample BRD pattern: data and reporting requirements should state data owners, refresh frequency and retention; migrations need a reconciliation and rollback plan.' },
  { source: 'Templates / Risk register template', tags: 'risk risks mitigation owner confirmed', text: 'Every risk records likelihood, impact, mitigation, owner role and trigger. Integration, staffing and scope risks must be reviewed at each phase gate.' },
];
const words = String(st.rag_query || '').split(/[^a-z0-9]+/).filter(w => w.length > 2);
const scored = CORPUS.map((c) => {
  const hits = c.tags.split(' ').filter(t => words.some(w => w === t || (w.length > 4 && t.length > 4 && (w.startsWith(t) || t.startsWith(w))))).length;
  return Object.assign({}, c, { score: hits });
}).filter(c => c.score > 0).sort((a, b) => b.score - a.score).slice(0, 8);
const chunks = scored.map((c, i) => ({ id: 'KB' + (i + 1), source: c.source, text: c.text, score: c.score }));
const triggers = (st.guardrail_triggers || []).slice();
if (!chunks.length) triggers.push('no_rag_hits');
return [{ json: Object.assign({}, st, { kb_chunks: chunks, rag_hits: chunks.length, guardrail_triggers: Array.from(new Set(triggers)) }) }];

const NL = String.fromCharCode(10);
const st = $('Knowledge Base (RAG with citations)').first(0, $runIndex).json;
const ORDER = ['engineering_plan', 'schedule', 'architecture', 'poc', 'tech_stack'];
const results = {};
const items = $input.all().map(i => i.json || {});
try { items.push($('2. Engineering Plan Generator').first(0, $runIndex).json || {}); } catch (e) { /* plan output unavailable */ }
items.forEach((r) => { if (r.agent_name && ORDER.includes(r.agent_name)) results[r.agent_name] = r; });
ORDER.forEach((a) => { if (!results[a]) results[a] = { agent_name: a, failed: true, output: null, schema_valid: false, schema_issues: ['agent_failed'], guardrail_triggers: ['agent_failed'] }; });
const strip = (o) => o ? JSON.stringify(o).slice(0, 6000) : 'NO VALID ARTIFACT';
const prompt = [
  'PROJECT: ' + st.project_name + '   REVIEW CYCLE: ' + st.cycle + ' (max 2 revisions)',
  '',
  '=== BRD SECTIONS ===',
  st.sections.map(s => '[' + s.id + '] ' + s.title + ': ' + String(s.content).slice(0, 1200)).join(NL),
  '',
  '=== KNOWLEDGE CHUNKS ===',
  st.kb_chunks.length ? st.kb_chunks.map(c => '[' + c.id + '] ' + c.text).join(NL) : 'NONE',
  '',
  '=== AGENT ARTIFACTS (claims are 0-indexed) ===',
  ORDER.map(a => '### ' + a + ' | assigned sections: ' + (st.routing_summary[a] || []).join(', ') + ' | schema_valid=' + results[a].schema_valid + NL + strip(results[a].output)).join(NL + NL),
].join(NL);
return [{ json: { results: results, critic_prompt: prompt } }];

const st = $('Knowledge Base (RAG with citations)').first(0, $runIndex).json;
const results = $('Prepare Critic Review').first(0, $runIndex).json.results;
const j = $input.first().json || {};
const arr = v => Array.isArray(v) ? v : [];
const r2 = x => Math.round(x * 100) / 100;
let cr = null;
const c = j.output && j.output[0] && j.output[0].content && j.output[0].content[0];
const raw = c ? c.text : null;
if (raw && typeof raw === 'object') cr = raw; else if (typeof raw === 'string') { try { cr = JSON.parse(raw); } catch (e) { cr = null; } }
const triggers = st.guardrail_triggers.slice();
if (!cr) { triggers.push('critic_unavailable'); cr = {}; }
const ca = cr.agents || {};
const ORDER = ['engineering_plan', 'schedule', 'architecture', 'poc', 'tech_stack'];
const agentScores = {}; const feedback = {}; const prevOut = {};
let allClaims = 0, goodClaims = 0;
ORDER.forEach((a) => {
  const r = results[a]; const k = ca[a] || {};
  prevOut[a] = r.output || null;
  const unsupported = new Set(arr(k.unsupported_claim_indexes).map(Number));
  const cited = arr(r.cited_indexes).filter(i => !unsupported.has(i)).length;
  const claims = Number(r.claims_count) || 0;
  allClaims += claims; goodClaims += cited;
  const g = claims ? Math.round(cited / claims * 100) : 0;
  const routed = st.routing_summary[a] || [];
  const miss = Array.from(new Set(arr(r.missing_sections).concat(arr(k.unaddressed_section_ids).map(String).filter(x => routed.includes(x)))));
  const comp = r.output ? Math.round((routed.length - miss.length) / Math.max(1, routed.length) * 100) : 0;
  const contr = arr(k.contradictions).length;
  const act = Math.max(0, Math.min(5, Number(k.actionability) || 0));
  const creep = arr(k.scope_creep);
  const below = [];
  if (g < 75) below.push('groundedness'); if (comp < 100) below.push('completeness'); if (contr > 0) below.push('consistency'); if (act < 4) below.push('actionability');
  const pass = !!r.schema_valid && below.length === 0 && creep.length === 0;
  const fb = [];
  if (!r.schema_valid) fb.push('Return a valid JSON object matching the contract. Issues: ' + arr(r.schema_issues).join(', '));
  if (g < 75) fb.push('Only ' + g + '% of claims are cited and supported (need 75%). Cite valid S#/KB# ids for every claim.');
  if (miss.length) fb.push('Address these assigned BRD sections: ' + miss.join(', '));
  arr(k.contradictions).forEach(x => fb.push('Resolve contradiction with ' + (x.with || 'another agent') + ': ' + x.description));
  if (act < 4) fb.push('Raise actionability (' + act + '/5): add owners, numbers and acceptance criteria.');
  creep.forEach(x => fb.push('Remove scope creep not in the BRD: ' + x));
  arr(k.feedback).forEach(x => fb.push(String(x)));
  feedback[a] = pass ? [] : fb;
  agentScores[a] = { groundedness_pct: g, completeness_pct: comp, contradictions: contr, actionability: act, scope_creep: creep.length, below_threshold: below, pass: pass, schema_valid: !!r.schema_valid, json_repairs: r.json_repair_attempts || 0, rag_hits: st.rag_hits, exec_ms: r.exec_ms || 0, input_hash: r.input_hash || '', output_hash: r.output_hash || '', guardrail_triggers: arr(r.guardrail_triggers) };
  if (creep.length) triggers.push(a + ':scope_creep');
  if (unsupported.size || arr(r.invalid_citations).length) triggers.push(a + ':hallucination_flag');
  if (!r.schema_valid) triggers.push(a + ':schema_contract_failed');
});

const failing = ORDER.filter(a => !agentScores[a].pass);
const needsRevision = failing.length > 0 && st.cycle < 2;
const history = arr(st.critic_history).concat([{ cycle: st.cycle, failing: failing, scores: agentScores }]);

const cross = arr(cr.cross_agent_contradictions);
const groundedness = allClaims ? Math.round(goodClaims / allClaims * 100) : 0;
const addressed = new Set();
ORDER.forEach(a => arr(results[a].output && results[a].output.brd_sections_addressed).forEach(id => addressed.add(String(id))));
const uncovered = st.all_section_ids.filter(id => !addressed.has(id));
const completeness = Math.round((st.all_section_ids.length - uncovered.length) / Math.max(1, st.all_section_ids.length) * 100);
const contradictions = cross.length + ORDER.reduce((s, a) => s + agentScores[a].contradictions, 0);
const actionability = r2(ORDER.reduce((s, a) => s + agentScores[a].actionability, 0) / ORDER.length);
const below = [];
if (groundedness < 75) below.push('Groundedness'); if (completeness < 100) below.push('Completeness'); if (contradictions > 0) below.push('Consistency'); if (actionability < 4) below.push('Actionability');
const overall = r2((groundedness / 20 + completeness / 20 + Math.max(0, 5 - 2 * contradictions) + actionability) / 4);
let badge = 'Green';
if (below.length >= 2 || overall < 3) badge = 'Red'; else if (below.length === 1 || overall < 4) badge = 'Amber';
const reasons = below.map(d => d + ' below threshold');
if (badge === 'Green' && failing.length) { badge = 'Amber'; }
if (failing.length) reasons.push('Revision cap reached (2 cycles) without passing: ' + failing.join(', '));
if (!st.rag_hits) { if (badge === 'Green') badge = 'Amber'; reasons.push('No knowledge-base hits: outputs rely on the BRD only'); }
const schemaRate = Math.round(ORDER.filter(a => agentScores[a].schema_valid).length / ORDER.length * 100);
const pipelineMs = Date.now() - st.start_ms;

if (needsRevision) {
  return [{ json: { needs_revision: true, base: { run_id: st.run_id, start_ms: st.start_ms, project_name: st.project_name, em_email: st.em_email, brd_hash: st.brd_hash, sections: st.sections, all_section_ids: st.all_section_ids, guardrail_triggers: Array.from(new Set(triggers)) }, critic_state: { cycle: st.cycle + 1, feedback: feedback, previous_outputs: prevOut, history: history } } }];
}
return [{ json: {
  needs_revision: false,
  run_id: st.run_id, project_name: st.project_name, em_email: st.em_email, brd_hash: st.brd_hash,
  sections_meta: st.sections.map(s => ({ id: s.id, title: s.title, category: s.category })),
  routing_summary: st.routing_summary, kb_sources: st.kb_chunks.map(k => k.id + ': ' + k.source),
  artifacts: prevOut, agent_scores: agentScores, critic_history: history, revision_cycles: st.cycle,
  unresolved_feedback: feedback, cross_agent_contradictions: cross,
  em_summary: cr.em_summary || '', open_questions: arr(cr.open_questions_for_em),
  evaluation: { groundedness_pct: groundedness, completeness_pct: completeness, uncovered_sections: uncovered, contradictions: contradictions, actionability: actionability, overall_score: overall, below_threshold: below, schema_parse_rate: schemaRate, pipeline_ms: pipelineMs, success_criteria: { completeness_100: completeness === 100, actionability_gte_4: actionability >= 4, under_5_min: pipelineMs < 300000 } },
  badge: badge, badge_reasons: reasons,
  guardrail_triggers: Array.from(new Set(triggers)),
} }];

const d = $input.first().json;
const ev = d.evaluation;
const esc = s => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const arr = v => Array.isArray(v) ? v : [];
const COLOR = { Green: '#2e7d32', Amber: '#ef6c00', Red: '#c62828' };
const TITLES = { engineering_plan: '2. Engineering Plan', schedule: '3. Schedule Estimate', architecture: '4. Solution Architecture', poc: '5. PoC Plan', tech_stack: '6. Tech Stack Options' };
const SKIP = ['claims', 'brd_sections_addressed', 'ambiguities', 'assumptions', 'summary', 'reflection_notes'];
const fmt = (v) => { if (v === null || v === undefined) return ''; if (Array.isArray(v)) return v.map(x => typeof x === 'object' ? fmt(x) : String(x)).join(', '); if (typeof v === 'object') return Object.keys(v).map(k => k + ': ' + fmt(v[k])).join('; '); return String(v); };
const renderArtifact = (o) => {
  if (!o) return '<p><i>No artifact produced.</i></p>';
  let h = o.summary ? '<p>' + esc(o.summary) + '</p>' : '';
  Object.keys(o).filter(k => !SKIP.includes(k)).forEach((k) => {
    const v = o[k];
    if (Array.isArray(v)) h += '<p><b>' + esc(k.replace(/_/g, ' ')) + '</b></p><ul>' + v.slice(0, 12).map(x => '<li>' + esc(typeof x === 'object' ? fmt(x) : x) + '</li>').join('') + '</ul>';
    else if (v && typeof v === 'object') h += '<p><b>' + esc(k.replace(/_/g, ' ')) + ':</b> ' + esc(fmt(v)) + '</p>';
    else if (v !== undefined && v !== '') h += '<p><b>' + esc(k.replace(/_/g, ' ')) + ':</b> ' + esc(v) + '</p>';
  });
  const cl = arr(o.claims);
  if (cl.length) h += '<p><b>Source citations</b></p><ul>' + cl.slice(0, 12).map(c => '<li>' + esc(c.statement) + ' <i>[' + esc(arr(c.sources).join(', ')) + ']</i></li>').join('') + '</ul>';
  return h;
};
let html = '<h2 style="color:' + COLOR[d.badge] + '">' + esc(d.badge_label) + ' - ' + esc(d.project_name) + '</h2>';
html += '<p><b>EM action:</b> ' + esc(d.em_action) + '</p>';
html += '<p><b>Overall score:</b> ' + ev.overall_score + ' / 5 | <b>Critic revision cycles:</b> ' + d.revision_cycles + ' | <b>Run:</b> ' + esc(d.run_id) + '</p>';
if (d.badge_reasons.length) html += '<ul>' + d.badge_reasons.map(r => '<li>' + esc(r) + '</li>').join('') + '</ul>';
if (d.em_summary) html += '<p><b>Critic summary:</b> ' + esc(d.em_summary) + '</p>';
const row = (n, v, t, ok) => '<tr><td>' + n + '</td><td>' + v + '</td><td>' + t + '</td><td>' + (ok ? 'Pass' : '<b>Below</b>') + '</td></tr>';
html += '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Dimension</th><th>Value</th><th>Threshold</th><th>Status</th></tr>';
html += row('Groundedness', ev.groundedness_pct + '% claims cited', '>= 75%', ev.groundedness_pct >= 75);
html += row('Completeness', ev.completeness_pct + '% sections', '100%', ev.completeness_pct === 100);
html += row('Consistency', ev.contradictions + ' contradictions', '0', ev.contradictions === 0);
html += row('Actionability', ev.actionability + ' / 5', '>= 4', ev.actionability >= 4);
html += '</table>';
html += '<h3>Agent scorecard</h3><table border="1" cellpadding="4" cellspacing="0"><tr><th>Agent</th><th>Pass</th><th>Grounded</th><th>Complete</th><th>Contradictions</th><th>Action.</th></tr>';
Object.keys(d.agent_scores).forEach(a => { const s = d.agent_scores[a]; html += '<tr><td>' + TITLES[a] + '</td><td>' + (s.pass ? 'Yes' : '<b>No</b>') + '</td><td>' + s.groundedness_pct + '%</td><td>' + s.completeness_pct + '%</td><td>' + s.contradictions + '</td><td>' + s.actionability + '</td></tr>'; });
html += '</table>';
const cross = arr(d.cross_agent_contradictions);
if (cross.length) html += '<h3>Contradictions raised to the EM</h3><ul>' + cross.map(c => '<li><b>' + esc(arr(c.between).join(' vs ')) + ':</b> ' + esc(c.description) + (c.conservative_resolution ? ' <i>(conservative default: ' + esc(c.conservative_resolution) + ')</i>' : '') + '</li>').join('') + '</ul>';
const amb = []; Object.keys(d.artifacts).forEach(a => arr(d.artifacts[a] && d.artifacts[a].ambiguities).forEach(x => amb.push('[' + a + '] ' + (typeof x === 'object' ? (x.brd_ref || '') + ' ' + (x.item || '') : x))));
if (amb.length) html += '<h3>Ambiguities flagged (not guessed)</h3><ul>' + amb.slice(0, 20).map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>';
if (d.open_questions.length) html += '<h3>Open questions for the EM</h3><ul>' + d.open_questions.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>';
html += '<h3>Knowledge base sources</h3><ul>' + d.kb_sources.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>';
Object.keys(d.artifacts).forEach(a => { html += '<hr><h3>' + TITLES[a] + '</h3>' + renderArtifact(d.artifacts[a]); });
return [{ json: Object.assign({}, d, { report_html: html, subject: '[' + d.badge + '] Decision-ready engineering artifacts: ' + d.project_name }) }];

const d = $input.first().json;
return Object.keys(d.agent_scores).map((a) => {
  const s = d.agent_scores[a];
  const rev = d.critic_history.filter(h => h.cycle > 0 && Array.isArray(h.failing)).length ? d.critic_history.slice(0, -1).filter(h => h.failing.includes(a)).length : 0;
  return { json: {
    run_id: d.run_id, agent_name: a, input_hash: s.input_hash, output_hash: s.output_hash,
    output_chars: JSON.stringify(d.artifacts[a] || {}).length, rag_hits: s.rag_hits, rag_chunk_ids: d.kb_sources.join(' | '),
    critic_scores: JSON.stringify({ groundedness_pct: s.groundedness_pct, completeness_pct: s.completeness_pct, contradictions: s.contradictions, actionability: s.actionability }),
    overall_score: Math.round(((s.groundedness_pct / 20 + s.completeness_pct / 20 + Math.max(0, 5 - 2 * s.contradictions) + s.actionability) / 4) * 100) / 100,
    agent_badge: s.pass ? 'Pass' : (s.below_threshold.length >= 2 ? 'Red' : 'Amber'),
    revision_count: rev, exec_ms: s.exec_ms, guardrail_triggers: s.guardrail_triggers.join('; '),
    schema_valid: s.schema_valid, escalated: !s.pass,
  } };
});

const j = $input.first().json || {};
const d = (j.data && typeof j.data === 'object') ? j.data : j;
const find = (re) => { for (const k of Object.keys(d)) { if (re.test(k)) return d[k]; } return undefined; };
const rep = $('Build EM Report').first().json;
const decision = find(/decision/i) ? String(find(/decision/i)) : 'No response (timed out)';
const rating = Number(find(/rating/i)) || null;
const comments = String(find(/comment/i) || '');
return [{ json: {
  run_id: rep.run_id, project_name: rep.project_name, em_email: rep.em_email, brd_hash: rep.brd_hash,
  badge: rep.badge, evaluation: rep.evaluation, revision_cycles: rep.revision_cycles, guardrail_triggers: rep.guardrail_triggers,
  agents_escalated: Object.keys(rep.agent_scores).filter(a => !rep.agent_scores[a].pass).length,
  em_decision: decision, em_rating: rating, em_comments: comments, approved: /^approve/i.test(decision),
  export_package: {
    run_id: rep.run_id, project_name: rep.project_name, brd_hash: rep.brd_hash, generated_at: new Date().toISOString(),
    quality: { badge: rep.badge, reasons: rep.badge_reasons, evaluation: rep.evaluation, agent_scores: rep.agent_scores },
    em_review: { decision: decision, rating: rating, comments: comments },
    brd_sections: rep.sections_meta, routing: rep.routing_summary, knowledge_sources: rep.kb_sources,
    artifacts: rep.artifacts, critic_history: rep.critic_history, cross_agent_contradictions: rep.cross_agent_contradictions,
  },
} }];
